const body = $input.first().json.body;
const content = JSON.parse(body.choices[0].message.content);

const rows = [];

// Fila de cabecera
const ahora = new Date();
rows.push({
  A: 'CERTIFICACION',
  B: content.numero_certificacion || '',
  C: content.proyecto || '',
  D: '',
  E: '',
  F: '',
  G: ''
});
rows.push({
  A: 'Fecha',
  B: content.fecha || '',
  C: '',
  D: '',
  E: '',
  F: '',
  G: ''
});
rows.push({}); // separador

// Cabeceras de columnas
rows.push({
  A: 'Codigo',
  B: 'Ud',
  C: 'Descripcion',
  D: 'Cant. Acum.',
  E: 'Precio Unit.',
  F: 'Importe',
  G: 'Estado'
});

// Items
if (content.items && content.items.length > 0) {
  for (const item of content.items) {
    rows.push({
      A: item.codigo || '',
      B: item.unidad || '',
      C: item.descripcion || '',
      D: item.cantidad_acumulada || '',
      E: item.precio_unitario || '',
      F: item.importe || '',
      G: item.revisado ? 'Revisado' : 'Pendiente'
    });
  }
}

// Totales
rows.push({});
rows.push({
  A: 'TOTAL',
  B: '',
  C: '',
  D: '',
  E: '',
  F: content.total_importe || '',
  G: ''
});

return rows;
